:root {
  --card: #fffdf7;
  --ink: #263448;
  --muted: #68778a;
  --line: #d7e1e8;
  --blue: #2774a8;
  --blue-soft: #e4f2fb;
  --gold: #f3ba43;
}

.route-card {
  box-sizing: border-box;
  width: 460px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--card);
  color: var(--ink);
}

.route-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
}

.route-icon {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: var(--gold);
  font-size: 18px;
}

.status-badge {
  padding: 4px 8px;
  border-radius: 999px;
  background: var(--blue-soft);
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.5px;
}

.route-card h2 {
  margin: 0 0 3px;
  font-size: 19px;
  line-height: 1.2;
}

.route-time {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.route-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 13px;
}

.route-footer button {
  padding: 7px 10px;
  border: 0;
  border-radius: 7px;
  background: var(--blue);
  color: var(--card);
  font-size: 13px;
  font-weight: 700;
}
